add_action( 'template_redirect', 'perfectpixel_members_only_site', 1 );
add_filter( 'rest_authentication_errors', 'perfectpixel_members_only_rest' );

function perfectpixel_members_only_site() {
	if ( is_user_logged_in() || wp_doing_cron() || wp_doing_ajax() || ( defined( 'WP_CLI' ) && WP_CLI ) ) {
		return;
	}
	$path = (string) wp_parse_url( $_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH );
	foreach ( array_filter( array_map( 'trim', explode( ',', '{{members_only_exceptions}}' ) ) ) as $open ) {
		if ( 0 === strpos( $path, $open ) ) {
			return;
		}
	}
	if ( is_feed() ) {
		wp_die( 'Αυτό το site είναι ιδιωτικό.', '', array( 'response' => 403 ) );
	}
	auth_redirect(); // Redirects to wp-login.php and back after login.
}

function perfectpixel_members_only_rest( $result ) {
	if ( true === $result || is_wp_error( $result ) || is_user_logged_in() ) {
		return $result;
	}
	return new WP_Error( 'rest_forbidden', 'Αυτό το site είναι ιδιωτικό.', array( 'status' => 401 ) );
}
